FLoadoutRow UCompositeKeyLibrary::GetLoadoutRow(int32 StageKey, ESlot SlotKey, bool& bFound)
{
    const FLoadoutRow* Found = FCompositeKey::Loadout().FindByStageAndSlot(KeyOfStageAndSlot(StageKey, SlotKey));

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FLoadoutRow();
}

int32 UCompositeKeyLibrary::GetLoadoutRowCount()
{
    return FCompositeKey::Loadout().Records().Num();
}

FLoadoutRow UCompositeKeyLibrary::GetLoadoutRowAt(int32 Position, bool& bFound)
{
    const TArray<FLoadoutRow>& Rows = FCompositeKey::Loadout().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FLoadoutRow();
}


