bool UCompositeKeyLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FCompositeKey::ReadAll(BasePath, FileExtension);
}

bool FCompositeKey::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FLoadoutTable LoadedLoadout;

    if (!LoadedLoadout.Read(FPaths::Combine(BasePath, TEXT("Loadout") + FileExtension)))
    {
        return false;
    }
    FRouteTable LoadedRoute;

    if (!LoadedRoute.Read(FPaths::Combine(BasePath, TEXT("Route") + FileExtension)))
    {
        return false;
    }
    FGridTable LoadedGrid;

    if (!LoadedGrid.Read(FPaths::Combine(BasePath, TEXT("Grid") + FileExtension)))
    {
        return false;
    }
    FBeastTable LoadedBeast;

    if (!LoadedBeast.Read(FPaths::Combine(BasePath, TEXT("Beast") + FileExtension)))
    {
        return false;
    }
    FMoveTable LoadedMove;

    if (!LoadedMove.Read(FPaths::Combine(BasePath, TEXT("Move") + FileExtension)))
    {
        return false;
    }
    FBeastMoveTable LoadedBeastMove;

    if (!LoadedBeastMove.Read(FPaths::Combine(BasePath, TEXT("BeastMove") + FileExtension)))
    {
        return false;
    }
    FBeastNoteTable LoadedBeastNote;

    if (!LoadedBeastNote.Read(FPaths::Combine(BasePath, TEXT("BeastNote") + FileExtension)))
    {
        return false;
    }
    FMoveNoteTable LoadedMoveNote;

    if (!LoadedMoveNote.Read(FPaths::Combine(BasePath, TEXT("MoveNote") + FileExtension)))
    {
        return false;
    }

    LoadoutStorage = MoveTemp(LoadedLoadout);
    RouteStorage = MoveTemp(LoadedRoute);
    GridStorage = MoveTemp(LoadedGrid);
    BeastStorage = MoveTemp(LoadedBeast);
    MoveStorage = MoveTemp(LoadedMove);
    BeastMoveStorage = MoveTemp(LoadedBeastMove);
    BeastNoteStorage = MoveTemp(LoadedBeastNote);
    MoveNoteStorage = MoveTemp(LoadedMoveNote);

    return true;
}
